public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int n = sc.nextInt();
    int[] a = new int[n];

    for (int i = 0; i < n; i++) {
        a[i] = sc.nextInt();
    }

    sc.close();
    int mod = 998244353;
    int[] dp = new int[n];
    dp[0] = 1;

    for (int i = 0; i < n; i++) {
        for (int j = 1; i + a[i] * j < n; j++) {
            dp[i + a[i] * j] = (dp[i + a[i] * j] + dp[i]) % mod;
        }
    }

    int ans = 0;

    for (int i = 0; i < n; i++) {
        ans = (ans + dp[i]) % mod;
    }

    System.out.println(ans);
}
